186	// Decode the --key-hex argument, emitting the shared key-format diagnostic
187	// (which never echoes the submitted key) on failure.
188	bool parseKey(std::string_view command, std::string_view usage,
189	              const std::string& keyHex, std::vector<unsigned char>& key) {
190	    if (decodeHex(keyHex, key)) {
191	        return true;
192	    }
193	    std::cerr << "messagetag " << command
194	              << ": error: invalid --key-hex: expected a non-empty, "
195	                 "even-length string of hexadecimal characters (0-9, a-f, A-F); "
196	                 "every two characters denote one key byte and leading zeros must "
197	                 "be kept; a 0x prefix and whitespace are not accepted\n"
198	              << usage;
199	    return false;
200	}
201	
202	// Shared front half of both commands: parse only this command's accepted
203	// value-taking options, require every name in `required` to be present, and
204	// decode --key-hex. This bundles the three input-preparation stages that
205	// tag and verify otherwise maintain in duplicate:
206	//
207	//   1. option parsing (unknown argument / missing value -> exit 2 with this
208	//      command's own reason and usage -- the other command's option set and
209	//      usage are never seen here);
210	//   2. required-option checks (exit 2);
211	//   3. key-hex decoding (exit 2, before the message file is ever opened).
212	//
213	// Returns the exit code to use directly: 0 when every input is ready, or 2
214	// with the diagnostic already written. On success the collected option
215	// values (including an explicitly empty one, which keeps its own later
216	// format/read error) and the decoded key bytes are handed back.
217	int prepareInputs(int argc, char* argv[], std::string_view command,
218	                  std::string_view usage,
219	                  const std::vector<std::string_view>& accepted,
220	                  const std::vector<std::string_view>& required,
221	                  std::map<std::string, std::string>& opts,
222	                  std::vector<unsigned char>& key) {
223	    if (!parseValueOptions(argc, argv, command, usage, accepted, opts)) {
224	        return 2;
225	    }
226	    for (std::string_view name : required) {
227	        if (!requireOption(opts, command, usage, name)) {
228	            return 2;
229	        }
230	    }
231	    if (!parseKey(command, usage, opts["--key-hex"], key)) {
232	        return 2;
233	    }
234	    return 0;
235	}
236	
237	// Stream the message file into HMAC-SHA-256 a fixed-size chunk at a time.
238	// The message is never stored whole: regardless of file length, only one
239	// 64 KiB read buffer is needed on top of the constant-size HMAC context.
240	//
241	// The bytes are not interpreted as text: the file is opened in binary mode,
242	// trailing newlines are kept, line endings are not converted and zero bytes
243	// are preserved. An empty file simply yields no Update calls, which
244	// authenticates the empty message.
245	enum class HmacStatus { kSuccess, kReadError, kCryptoError };
246	
247	HmacStatus hmacSha256File(const std::vector<unsigned char>& key,
248	                          const std::string& path,
249	                          std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
250	                          std::size_t& macLength) {
251	    HMAC_CTX* rawCtx = HMAC_CTX_new();
252	    if (rawCtx == nullptr) {
253	        return HmacStatus::kCryptoError;
254	    }
255	    std::unique_ptr<HMAC_CTX, decltype(&HMAC_CTX_free)> ctx(rawCtx,
256	                                                            HMAC_CTX_free);
257	
258	    // Init with the key and SHA-256. HMAC_Init_ex performs the standard
259	    // RFC 2104 key normalization itself, so keys longer than the SHA-256
260	    // block size are hashed exactly as the standard requires; the resulting
261	    // tag is identical to the one-shot HMAC() interface on both OpenSSL
262	    // 1.1.1 and OpenSSL 3.x. The key is validated to be non-empty before
263	    // this is called, so key.data() is always valid.
264	    if (HMAC_Init_ex(ctx.get(), key.data(), static_cast<int>(key.size()),
265	                     EVP_sha256(), nullptr) != 1) {
266	        return HmacStatus::kCryptoError;
267	    }
268	
269	    std::ifstream in(path, std::ios::binary | std::ios::in);
270	    if (!in) {
271	        return HmacStatus::kReadError;
272	    }
273	
274	    std::array<char, 65536> buffer{};
275	    while (in.read(buffer.data(), static_cast<std::streamsize>(buffer.size()))) {
276	        if (HMAC_Update(ctx.get(),
277	                        reinterpret_cast<const unsigned char*>(buffer.data()),
278	                        static_cast<std::size_t>(in.gcount())) != 1) {
279	            return HmacStatus::kCryptoError;
280	        }
281	    }
282	    // A read error (including one that happens after part of the message has
